function minimumOperations(nums) {
  // Simulate the operations: after ops of them the array is nums from index 3 * ops on.
  const hasRepeat = (start) => {
    for (let a = start; a < nums.length; a++) {
      for (let b = a + 1; b < nums.length; b++) {
        if (nums[a] === nums[b]) return true;
      }
    }
    return false;
  };
  let ops = 0;
  while (hasRepeat(3 * ops)) ops++;
  return ops;
}

