function generate(rand, size) {
  if (size === 'small') {
    const n = 1 + Math.floor(rand() * 12);
    const range = 1 + Math.floor(rand() * 12);
    return [Array.from({ length: n }, () => 1 + Math.floor(rand() * range))];
  }
  // A random head followed by a distinct tail of random length, so the answer varies.
  const values = Array.from({ length: 100 }, (_, i) => i + 1);
  for (let i = values.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [values[i], values[j]] = [values[j], values[i]];
  }
  const tail = Math.floor(rand() * 101);
  const head = Array.from({ length: 100 - tail }, () => 1 + Math.floor(rand() * 100));
  return [[...head, ...values.slice(0, tail)]];
}
